// Brain: the team's long-term project memory, plain Markdown in `<project>/.gridkeeper/brain/` that every agent
// can read and write (format and storage: src-tauri/src/brain.rs; rules for agents: skills/agent-mission/SKILL.md).
// Pure and node-safe (unit-tested).
//
//   notes/<slug>.md   confirmed memories, one per file: a tiny front matter + a few concrete lines
//   inbox/<slug>.md   suggestions waiting for the user's approval (same format, confidence: suggested)
//   INDEX.md          generated by Gridkeeper from both folders; never edited by hand
//
//   ---
//   title: Refresh tokens live in the OS keychain
//   kind: decision            (decision | convention | gotcha | howto | fact | context)
//   tags: [auth, security]
//   source: task "Design the token storage"
//   created: 2026-10-18
//   updated: 2026-10-18
//   confidence: confirmed     (confirmed | suggested)
//   supersedes: token-file    (optional)
//   ---
//   We store refresh tokens in the OS keychain, never on disk.
//
// This module: front matter parsing and editing (unknown keys, key order and line endings are kept), new note
// text, slugs, kind guessing, duplicate detection, scrubbing (the replay recorder's rules: no absolute paths,
// e-mail addresses or secret-looking tokens), the brief line, and capture: turning mission board changes, review
// outcomes and lead decisions into short suggested memories.

import { scrubText } from "../replay/events";
import { slugify, taskBlockEnd, type MissionDoc, type Task } from "./missionDoc";

export type BrainKind = "decision" | "convention" | "gotcha" | "howto" | "fact" | "context";

/** Display order (matches INDEX.md sections). */
export const BRAIN_KINDS: readonly BrainKind[] = ["decision", "convention", "gotcha", "howto", "fact", "context"];

export const KIND_LABEL: Record<BrainKind, string> = {
  decision: "decision",
  convention: "convention",
  gotcha: "gotcha",
  howto: "how-to",
  fact: "fact",
  context: "context",
};

/** One-character mark per kind for the terminal-style lists. */
export const KIND_MARK: Record<BrainKind, string> = { decision: "◆", convention: "≡", gotcha: "!", howto: "→", fact: "·", context: "○" };

export const MAX_NOTE_BYTES = 16 * 1024;
export const MAX_SLUG_LEN = 80;
export const MAX_TITLE = 120;
/** Captured suggestions are short: at most this many characters of body. */
export const SUGGESTION_BODY_MAX = 600;

/** Same normalization as Rust `brain::normalize_kind` (unknown → fact; person-free-context → context). */
export function normalizeKind(raw: string | null | undefined): BrainKind {
  const k = (raw ?? "").toLowerCase().replace(/[^a-z0-9]/g, "");
  switch (k) {
    case "decision":
    case "decisions":
    case "adr":
      return "decision";
    case "convention":
    case "conventions":
    case "rule":
    case "rules":
    case "style":
      return "convention";
    case "gotcha":
    case "gotchas":
    case "pitfall":
    case "pitfalls":
    case "warning":
    case "caveat":
      return "gotcha";
    case "howto":
    case "howtos":
    case "recipe":
    case "guide":
      return "howto";
    case "context":
    case "personfreecontext":
    case "background":
      return "context";
    default:
      return "fact";
  }
}

/** A bare portable file stem, as Rust `brain::is_valid_slug`. */
export function isValidSlug(s: string): boolean {
  if (!s || s.length > MAX_SLUG_LEN || !/^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(s) || s.includes("..") || s.endsWith(".")) return false;
  const stem = s.split(".")[0].toLowerCase();
  return !/^(con|prn|aux|nul|com\d|lpt\d)$/.test(stem);
}

/** Local date as YYYY-MM-DD. */
export function today(d: Date = new Date()): string {
  const p = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())}`;
}

// ---- parsing ------------------------------------------------------------------------------------------

export interface ParsedNote {
  /** Lowercase key → value, in file order (a YAML block list is joined with ", "). */
  fields: [string, string][];
  body: string;
  hasFrontMatter: boolean;
}

const BOM = String.fromCharCode(0xfeff);

const KEY_RE = /^[A-Za-z][A-Za-z0-9_-]{0,31}$/;

function unquote(v: string): string {
  const t = v.trim();
  if (t.length >= 2 && ((t.startsWith('"') && t.endsWith('"')) || (t.startsWith("'") && t.endsWith("'")))) return t.slice(1, -1);
  return t;
}

function splitLines(text: string): string[] {
  return (text.startsWith(BOM) ? text.slice(1) : text).split("\n").map((l) => (l.endsWith("\r") ? l.slice(0, -1) : l));
}

/** Index of the line that closes a front matter starting on line 0, or -1. */
function closeIndex(lines: readonly string[]): number {
  if (lines.length === 0 || lines[0].trimEnd() !== "---") return -1;
  for (let i = 1; i < Math.min(lines.length, 65); i++) {
    const t = lines[i].trimEnd();
    if (t === "---" || t === "...") return i;
  }
  return -1;
}

/** Split front matter and body (lenient, never throws; same rules as Rust `brain::parse_note`). */
export function parseNote(text: string): ParsedNote {
  const lines = splitLines(text);
  const end = closeIndex(lines);
  if (end < 0) return { fields: [], body: lines.join("\n").replace(/^\n+|\n+$/g, ""), hasFrontMatter: false };
  const fields: [string, string][] = [];
  let listKey = -1;
  for (const l of lines.slice(1, end)) {
    const t = l.trim();
    const item = t.startsWith("- ") ? t.slice(2) : t === "-" ? "" : null;
    if (listKey >= 0 && item !== null) {
      const v = unquote(item);
      if (v) fields[listKey][1] = fields[listKey][1] ? `${fields[listKey][1]}, ${v}` : v;
      continue;
    }
    listKey = -1;
    const i = l.indexOf(":");
    if (i < 0) continue;
    const key = l.slice(0, i).trim().toLowerCase();
    if (!KEY_RE.test(key)) continue;
    const value = unquote(l.slice(i + 1));
    if (!value) listKey = fields.length;
    fields.push([key, value]);
  }
  return { fields, body: lines.slice(end + 1).join("\n").replace(/^\n+|\n+$/g, ""), hasFrontMatter: true };
}

export function fieldOf(p: ParsedNote, key: string): string | null {
  const f = p.fields.find(([k]) => k === key);
  const v = f?.[1].trim();
  return v ? v : null;
}

function normalizeTag(raw: string): string | null {
  let out = "";
  for (const c of unquote(raw).trim().replace(/^#+/, "").trim().toLowerCase()) {
    if (/[\p{L}\p{N}./+-]/u.test(c)) out += c;
    else if ((c === " " || c === "_") && !out.endsWith("-")) out += "-";
  }
  out = [...out.replace(/^-+|-+$/g, "")].slice(0, 32).join("");
  return out || null;
}

/** "[a, b]", "a, b" or "#a #b"-free lists → normalized unique tags (at most 12), as Rust `brain::parse_tags`. */
export function parseTags(raw: string | null | undefined): string[] {
  const inner = (raw ?? "").trim().replace(/^\[/, "").replace(/\]$/, "");
  const out: string[] = [];
  for (const part of inner.split(",")) {
    const t = normalizeTag(part);
    if (t && !out.includes(t)) out.push(t);
    if (out.length === 12) break;
  }
  return out;
}

export function formatTags(tags: readonly string[]): string {
  return `[${tags.join(", ")}]`;
}

export interface NoteFields {
  title: string;
  kind: BrainKind;
  tags: string[];
  source: string;
  created: string;
  updated: string;
  confidence: "confirmed" | "suggested";
  supersedes: string;
}

/** Typed front matter + body of a note ("" for missing fields; kind / confidence normalized). */
export function noteFields(text: string, inbox = false): NoteFields & { body: string } {
  const p = parseNote(text);
  const get = (k: string) => fieldOf(p, k) ?? "";
  const conf = get("confidence").toLowerCase();
  return {
    title: get("title"),
    kind: normalizeKind(get("kind")),
    tags: parseTags(get("tags")),
    source: get("source"),
    created: get("created"),
    updated: get("updated"),
    confidence: conf === "confirmed" || conf === "suggested" ? conf : inbox ? "suggested" : "confirmed",
    supersedes: get("supersedes").replace(/\.md$/i, ""),
    body: p.body,
  };
}

const FIELD_ORDER = ["title", "kind", "tags", "source", "created", "updated", "confidence", "supersedes"];

const oneLine = (s: string) => s.replace(/[\r\n]+/g, " ").replace(/\s{2,}/g, " ").trim();

/**
 * Rewrite a note: set front matter fields (null / "" removes a key), optionally replace the body. Unknown keys,
 * key order and the file's line endings stay; missing keys are added before the closing "---" (in the standard
 * order); a note without front matter gets one. Mirrors Rust `brain::set_fields`.
 */
export function editNote(text: string, set: Readonly<Record<string, string | null>>, body?: string): string {
  const bom = text.startsWith(BOM);
  const raw = bom ? text.slice(1) : text;
  const eol = raw.includes("\r\n") ? "\r\n" : "\n";
  const lines = splitLines(raw);
  const end = closeIndex(lines);
  const rest = end >= 0 ? lines.slice(end + 1) : lines;
  const adds = Object.values(set).some((v) => v !== null && oneLine(v) !== "");
  let head: string[] | null = end >= 0 ? lines.slice(0, end + 1) : adds ? ["---", "---"] : null;
  if (head) {
    const h = head;
    const keyOf = (l: string) => (l.includes(":") && !l.trimStart().startsWith("-") ? l.slice(0, l.indexOf(":")).trim().toLowerCase() : null);
    const rank = (k: string) => (FIELD_ORDER.includes(k) ? FIELD_ORDER.indexOf(k) : FIELD_ORDER.length);
    for (const key of Object.keys(set).sort((a, b) => rank(a) - rank(b))) {
      const value = set[key];
      const clean = value === null ? "" : oneLine(value);
      const at = h.findIndex((l, i) => i > 0 && i < h.length - 1 && keyOf(l) === key);
      if (at >= 0) {
        // A block list under the key belongs to the old value.
        let n = 0;
        while (at + 1 + n < h.length - 1 && h[at + 1 + n].trimStart().startsWith("-")) n++;
        const spelled = h[at].slice(0, h[at].indexOf(":"));
        if (clean) h.splice(at, 1 + n, `${spelled}: ${clean}`);
        else h.splice(at, 1 + n);
      } else if (clean) h.splice(h.length - 1, 0, `${key}: ${clean}`);
    }
    if (end < 0 && h.length === 2) head = null;
  }
  let bodyLines = rest;
  if (body !== undefined) {
    const b = body.replace(/\r\n?/g, "\n").replace(/^\n+|\n+$/g, "");
    bodyLines = b ? [...b.split("\n"), ""] : [""];
  }
  const out = [...(head ?? []), ...bodyLines].join(eol);
  return bom ? BOM + out : out;
}

export interface NewNote {
  title: string;
  kind: BrainKind;
  tags?: readonly string[];
  source?: string;
  confidence: "confirmed" | "suggested";
  supersedes?: string | null;
  body: string;
  /** YYYY-MM-DD (default: today). */
  date?: string;
}

/** Text of a brand-new note (LF endings). */
export function newNoteText(n: NewNote): string {
  const date = n.date ?? today();
  const lines = ["---", `title: ${oneLine(n.title) || "Untitled"}`, `kind: ${n.kind}`, `tags: ${formatTags(n.tags ?? [])}`];
  if (n.source && oneLine(n.source)) lines.push(`source: ${oneLine(n.source)}`);
  lines.push(`created: ${date}`, `updated: ${date}`, `confidence: ${n.confidence}`);
  if (n.supersedes) lines.push(`supersedes: ${n.supersedes}`);
  lines.push("---");
  const body = n.body.replace(/\r\n?/g, "\n").trim();
  if (body) lines.push(body);
  return `${lines.join("\n")}\n`;
}

/** A free slug for a title: slugified, cut to 48 characters, "-2", "-3", … when taken (case-insensitive). */
export function slugForTitle(title: string, taken: Iterable<string>): string {
  const used = new Set([...taken].map((s) => s.toLowerCase()));
  let base = slugify(title).slice(0, 48).replace(/-+$/, "");
  if (!isValidSlug(base)) base = base ? `note-${base}`.slice(0, 48).replace(/-+$/, "") : "note";
  if (!isValidSlug(base)) base = "note";
  if (!used.has(base)) return base;
  for (let n = 2; n < 10_000; n++) {
    const s = `${base}-${n}`;
    if (!used.has(s)) return s;
  }
  return `${base}-${Date.now()}`;
}

// ---- scrubbing, kinds, duplicates ---------------------------------------------------------------------

/** One line with paths, e-mails and secret-looking tokens removed (the replay recorder's rules), cut to `max`. */
export function scrubLine(raw: string | null | undefined, max = 200): string {
  return scrubText(raw, max);
}

/** Multi-line text scrubbed line by line: at most `maxLines` non-empty lines, `max` characters in total. */
export function scrubBody(raw: string | null | undefined, max = SUGGESTION_BODY_MAX, maxLines = 8): string {
  const out: string[] = [];
  let used = 0;
  for (const line of (raw ?? "").split(/\r?\n/)) {
    const bullet = /^\s*([-*+]|\d{1,3}[.)])\s+/.exec(line)?.[0].trim() ?? "";
    const s = scrubText(line.replace(/^\s*([-*+]|\d{1,3}[.)])\s+/, ""), 400);
    if (!s) continue;
    const l = bullet ? `${bullet} ${s}` : s;
    if (used + l.length > max) {
      const room = max - used;
      if (room > 20) out.push(`${l.slice(0, room - 1).trimEnd()}…`);
      break;
    }
    out.push(l);
    used += l.length + 1;
    if (out.length >= maxLines) break;
  }
  return out.join("\n");
}

const DECISION_RE = /\b(decided|decision|we will|we'll|we chose|we picked|agreed|going with|settled on|approved)\b/i;
const CONVENTION_RE = /\b(always|never|must|do not|don't|convention|naming|prefer)\b/i;
const GOTCHA_RE = /\b(careful|beware|gotcha|pitfall|workaround|flaky|breaks|broke|broken|fails?|failing|crash(es|ed)?|bug|blocked|blocker|watch out|caveat|requires?|needs?)\b/i;
const HOWTO_RE = /^(to |how to |run |use |install |set |build |start |deploy )|\b(npm|pnpm|yarn|cargo|make|pip|go) (run|test|build|install)\b/i;

/** Best-guess kind of a free-text memory. */
export function guessKind(text: string): BrainKind {
  const t = text.trim();
  if (DECISION_RE.test(t)) return "decision";
  if (CONVENTION_RE.test(t)) return "convention";
  if (HOWTO_RE.test(t)) return "howto";
  if (GOTCHA_RE.test(t)) return "gotcha";
  return "fact";
}

/** A title from free text: the first sentence, markers stripped, capitalized, cut to `max`. */
export function titleFrom(text: string, max = 72): string {
  let t = oneLine(text)
    .replace(/^([-*+]|\d{1,3}[.)])\s+/, "")
    .replace(/^(note|lgtm|fyi|decision|gotcha|tip)\s*[:—–-]\s*/i, "")
    .trim();
  const m = /^(.+?[.!?])(\s|$)/.exec(t);
  if (m && m[1].length >= 12) t = m[1].replace(/[.!]$/, "");
  if (t.length > max) t = `${t.slice(0, max - 1).replace(/\s+\S*$/, "").trimEnd() || t.slice(0, max - 1)}…`;
  return t ? t[0].toUpperCase() + t.slice(1) : "";
}

const STOP = new Set(["the", "and", "for", "with", "this", "that", "are", "was", "not", "but", "our", "you", "from", "into", "have", "has", "will", "all", "any", "can"]);

function words(s: string): Set<string> {
  const out = new Set<string>();
  for (const w of s.toLowerCase().split(/[^\p{L}\p{N}]+/u)) if (w.length > 2 && !STOP.has(w)) out.add(w);
  return out;
}

/** Jaccard similarity of the significant words of two texts (0..1). */
export function similarity(a: string, b: string): number {
  const x = words(a);
  const y = words(b);
  if (x.size === 0 || y.size === 0) return 0;
  let both = 0;
  for (const w of x) if (y.has(w)) both++;
  return both / (x.size + y.size - both);
}

export interface Comparable {
  title: string;
  /** Body or excerpt. */
  excerpt: string;
}

/** A near-duplicate of something already in the brain (same / similar title, or a very similar body). */
export function isDuplicate(c: { title: string; body: string }, existing: readonly Comparable[]): boolean {
  const t = c.title.trim().toLowerCase();
  for (const e of existing) {
    if (t && e.title.trim().toLowerCase() === t) return true;
    if (similarity(c.title, e.title) >= 0.7) return true;
    if (words(c.body).size >= 3 && similarity(c.body, e.excerpt) >= 0.6) return true;
    if (similarity(`${c.title} ${c.body}`, `${e.title} ${e.excerpt}`) >= 0.75) return true;
  }
  return false;
}

// ---- paths and the brief line -------------------------------------------------------------------------

const sepOf = (p: string) => (p.includes("\\") || !p.includes("/") ? "\\" : "/");

export interface BrainPaths {
  dir: string;
  index: string;
  notes: string;
  inbox: string;
}

/** Brain paths of a project folder (same separator style). */
export function brainPaths(projectDir: string): BrainPaths {
  const p = oneLine(projectDir).replace(/[\\/]+$/, "");
  const sep = sepOf(p);
  const dir = `${p}${sep}.gridkeeper${sep}brain`;
  return { dir, index: `${dir}${sep}INDEX.md`, notes: `${dir}${sep}notes${sep}`, inbox: `${dir}${sep}inbox${sep}` };
}

/** Brain paths from a mission file path (`<project>\.gridkeeper\mission.md`). */
export function brainPathsOfMission(missionPath: string): BrainPaths {
  const p = oneLine(missionPath);
  const gk = p.replace(/[\\/][^\\/]*$/, "");
  return brainPaths(gk.replace(/[\\/]\.gridkeeper$/i, "") || gk);
}

/** The brain part of a brief (one line): read INDEX.md first, suggest memories in inbox/ in the note format. */
export function brainBriefText(missionPath: string): string {
  const b = brainPathsOfMission(missionPath);
  return oneLine(
    `Project memory: read ${b.index} first (if it exists) and open the notes relevant to your task. When you learn something the next agent must know (a decision, convention, gotcha, how-to or fact), create ONE new file ${b.inbox}<short-slug>.md: a line '---', 'title: <one line>', 'kind: decision|convention|gotcha|howto|fact|context', 'tags: [a, b]', 'source: <your task>', 'confidence: suggested', a line '---', then 1-5 short factual lines. Never edit confirmed notes in ${b.notes} and never write secrets, tokens, e-mail addresses or personal data there.`,
  );
}

// ---- capture --------------------------------------------------------------------------------------------

export interface Suggestion {
  /** Stable key of what triggered it (dedupe within a session). */
  key: string;
  title: string;
  kind: BrainKind;
  tags: string[];
  source: string;
  body: string;
}

const NOTE_RE = /^\s*(?:[-*+]|\d{1,3}[.)])\s+note:\s*(.+)$/i;

/** The `- note: …` sub-lines under the task on `line` (its block). */
export function taskNotes(text: string, line: number): string[] {
  const end = taskBlockEnd(text, line);
  if (end === null) return [];
  const lines = text.split(/\r?\n/);
  const out: string[] = [];
  for (let i = line + 1; i < end; i++) {
    const m = NOTE_RE.exec(lines[i]);
    if (m && m[1].trim()) out.push(m[1].trim());
  }
  return out;
}

/** Reason and bare task text of a blocked task ("blocked: <reason> — <task>" or "Blocked: <reason>"). */
export function blockedReason(text: string): { reason: string; task: string } {
  const board = /^\s*blocked:\s*(.+?)\s+—\s+(.+)$/i.exec(text);
  if (board) return { reason: board[1].trim(), task: board[2].trim() };
  const plain = /^\s*blocked\b\s*[:—–-]?\s*(.+)$/i.exec(text);
  if (plain) return { reason: plain[1].trim(), task: plain[1].trim() };
  return { reason: text.trim(), task: text.trim() };
}

const tkey = (t: Pick<Task, "text" | "owners">) => `${t.text}|${t.owners.join(",")}`;
/** A review / verification task: by its wording, or owned by a reviewer / verifier ("@reviewer", "@codex-reviewer"). */
const isReviewTask = (t: Pick<Task, "text" | "owners">) => /^(review|verify|check|test)\b/i.test(t.text.trim()) || t.owners.some((o) => /review|verif/.test(o));
const FIX_RE = /^fix\b\s*[:—–-]?\s*/i;

function src(kind: "task" | "review" | "blocker" | "lead", text: string): string {
  const t = scrubLine(text, 120);
  if (kind === "lead") return "lead message";
  return t ? `${kind} “${t}”` : kind;
}

export interface BoardSnapshot {
  text: string;
  doc: MissionDoc;
}

/**
 * Suggestions from one mission board change (pure). Triggers:
 * - a task turned done with `- note: …` sub-lines → one memory per note (kind guessed; at most 2);
 * - a review task turned done with an LGTM note → a "decision" (approved);
 * - a task left the blocked state → a "gotcha" with the blocker reason;
 * - new `fix: …` tasks appeared (a review's fix list) → one "gotcha" listing them.
 */
export function suggestFromBoard(prev: BoardSnapshot, next: BoardSnapshot, date: string = today()): Suggestion[] {
  const out: Suggestion[] = [];
  const prevByKey = new Map(prev.doc.tasks.map((t) => [tkey(t), t]));
  const prevByLine = new Map(prev.doc.tasks.map((t) => [t.line, t]));
  const nextKeys = new Set(next.doc.tasks.map(tkey));
  const prevTexts = new Set(prev.doc.tasks.map((t) => t.text.toLowerCase()));
  const sameOwners = (a: Task, b: Task) => a.owners.join(",") === b.owners.join(",");
  const before = (t: Task): Task | undefined => {
    const k = prevByKey.get(tkey(t));
    if (k) return k;
    const l = prevByLine.get(t.line);
    if (l && sameOwners(l, t) && !nextKeys.has(tkey(l))) return l;
    // Unblocked on the board: the "blocked: <reason> — " prefix was removed.
    return prev.doc.tasks.find((p) => p.state === "blocked" && sameOwners(p, t) && blockedReason(p.text).task === t.text && !nextKeys.has(tkey(p)));
  };

  for (const t of next.doc.tasks) {
    const was = before(t);
    if (!was) continue;
    if (t.state === "done" && was.state !== "done") {
      const notes = taskNotes(next.text, t.line);
      const lgtm = notes.find((n) => /^lgtm\b/i.test(n));
      if (lgtm !== undefined && isReviewTask(t)) {
        const rest = scrubBody(lgtm.replace(/^lgtm\b[\s:—–.,!-]*/i, ""), 300);
        out.push({
          key: `lgtm|${tkey(t)}`,
          title: titleFrom(`Approved: ${t.text}`),
          kind: "decision",
          tags: ["review"],
          source: src("review", t.text),
          body: `Review “${scrubLine(t.text, 160)}” ended with LGTM on ${date}.${rest ? ` ${rest}` : ""}`,
        });
      }
      for (const n of notes.filter((x) => x !== lgtm).slice(0, 2)) {
        const body = scrubBody(n);
        if (body.split(/\s+/).length < 3) continue;
        out.push({
          key: `note|${tkey(t)}|${n}`,
          title: titleFrom(body),
          kind: guessKind(body),
          tags: [],
          source: src("task", t.text),
          body: `${body}\n(from the task “${scrubLine(t.text, 160)}”)`,
        });
      }
    }
    if (was.state === "blocked" && t.state !== "blocked") {
      const { reason, task } = blockedReason(was.text);
      const why = scrubLine(reason, 160);
      if (why) {
        out.push({
          key: `unblocked|${tkey(was)}`,
          title: titleFrom(`Blocker: ${why}`),
          kind: "gotcha",
          tags: [],
          source: src("blocker", task),
          body: `“${scrubLine(task, 160)}” was blocked: ${why}. Unblocked on ${date}.`,
        });
      }
    }
  }

  const fixes = next.doc.tasks.filter((t) => FIX_RE.test(t.text) && !prevTexts.has(t.text.toLowerCase()) && t.state !== "done");
  if (fixes.length > 0) {
    const items = fixes.map((f) => scrubLine(f.text.replace(FIX_RE, ""), 140)).filter(Boolean);
    if (items.length) {
      const more = items.length > 1 ? ` (+${items.length - 1} more)` : "";
      out.push({
        key: `fixes|${items.join("|")}`,
        title: titleFrom(`Review found: ${items[0]}`, 72 - more.length) + more,
        kind: "gotcha",
        tags: ["review"],
        source: "review fix list",
        body: ["A review asked for these fixes:", ...items.slice(0, 5).map((i) => `- ${i}`)].join("\n"),
      });
    }
  }
  return out;
}

const DECISION_WORDS_RE = /\b(decided|we will|we'll|always|never)\b/i;

/** Suggestions from a lead's outbox message (pure): sentences with "decided", "we will", "always" or "never". */
export function suggestFromOutbox(text: string): Suggestion[] {
  const bare = text.replace(/^\s*\[(?:review request )?from [^\]]*\]\s*/i, "");
  const sentences = bare
    .replace(/\r?\n+/g, " ")
    .split(/(?<=[.!?;])\s+/)
    .map((s) => s.trim())
    .filter((s) => DECISION_WORDS_RE.test(s) && s.split(/\s+/).length >= 4);
  return sentences.slice(0, 2).map((s) => {
    const body = scrubBody(s, 300);
    return {
      key: `lead|${s}`,
      title: titleFrom(body),
      kind: /\b(always|never)\b/i.test(s) ? "convention" : "decision",
      tags: [],
      source: "lead message",
      body,
    };
  });
}

/** A compose-dialog draft from selected text (Mission Control selection, palette). */
export function draftFromText(text: string): { title: string; kind: BrainKind; body: string } {
  const body = scrubBody(text, 1200, 20);
  return { title: titleFrom(body), kind: guessKind(body), body };
}
